import Link from "next/link";
import ListGroup from "react-bootstrap/ListGroup";

export default function AccountNavigation() {
  return (
    <ListGroup
      className="rounded-0"
      style={{ width: "200px" }}
    >
      <ListGroup.Item
        action
        className="border-0 ps-3 text-danger fw-bold"
      >
        <Link
          href="/account/profile"
          className="text-danger text-decoration-none"
        >
          Profile
        </Link>
      </ListGroup.Item>

      <ListGroup.Item action className="border-0 ps-3">
        <Link
          href="/account/settings"
          className="text-dark text-decoration-none"
        >
          Settings
        </Link>
      </ListGroup.Item>

      <ListGroup.Item action className="border-0 ps-3">
        <Link
          href="/account/notifications"
          className="text-dark text-decoration-none"
        >
          Notifications
        </Link>
      </ListGroup.Item>

      <ListGroup.Item action className="border-0 ps-3">
        <Link
          href="/account/files"
          className="text-dark text-decoration-none"
        >
          Files
        </Link>
      </ListGroup.Item>
    </ListGroup>
  );
}
